// ========================================
// Code Node 2 — Datum extrahieren & ISO konvertieren
// Timezone-sicher: immer Europe/Berlin als Referenz
// ========================================

const text = $json.cleanedText.toLowerCase();

// Berliner Datum als Referenz
const now = new Date();
const berlinNow = new Date(now.toLocaleString("en-US", { timeZone: "Europe/Berlin" }));

function toISO(date) {
  const pad = (n) => String(n).padStart(2, "0");
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

let isoDate = null;

// ---------- 1. Konkretes Datum (9.9.2026 / 09.09.26 / 9. September 2026) ----------
const monthNames = {
  januar:1, februar:2, märz:3, april:4, mai:5, juni:6,
  juli:7, august:8, september:9, oktober:10, november:11, dezember:12
};

// Format: 9.9.2026 oder 09.09.2026 oder 9.9.26
const numericDate = text.match(/(\d{1,2})\.(\d{1,2})\.(\d{2,4})/);
if (numericDate) {
  const day   = parseInt(numericDate[1], 10);
  const month = parseInt(numericDate[2], 10) - 1;
  let year    = parseInt(numericDate[3], 10);
  if (year < 100) year += 2000;
  const d = new Date(year, month, day);
  isoDate = toISO(d);
}

// Format: 9. September 2026 oder 9. September
if (!isoDate) {
  for (const [name, month] of Object.entries(monthNames)) {
    const pattern = new RegExp(`(\\d{1,2})\\.?\\s*${name}\\s*(\\d{4})?`);
    const match = text.match(pattern);
    if (match) {
      const day  = parseInt(match[1], 10);
      const year = match[2] ? parseInt(match[2], 10) : berlinNow.getFullYear();
      const d    = new Date(year, month - 1, day);
      isoDate    = toISO(d);
      break;
    }
  }
}

// ---------- 2. Relative Daten ----------
if (!isoDate) {
  if (text.includes("übermorgen")) {
    const d = new Date(berlinNow);
    d.setDate(berlinNow.getDate() + 2);
    isoDate = toISO(d);
  } else if (text.includes("morgen")) {
    const d = new Date(berlinNow);
    d.setDate(berlinNow.getDate() + 1);
    isoDate = toISO(d);
  } else if (text.includes("heute")) {
    isoDate = toISO(berlinNow);
  }
}

// ---------- 3. Wochentage ----------
if (!isoDate) {
  const weekdays = {
    sonntag:0, montag:1, dienstag:2, mittwoch:3,
    donnerstag:4, freitag:5, samstag:6,
  };
  for (const [day, value] of Object.entries(weekdays)) {
    if (text.includes(day)) {
      const d = new Date(berlinNow);
      let diff = value - berlinNow.getDay();
      if (diff <= 0) diff += 7;
      d.setDate(berlinNow.getDate() + diff);
      isoDate = toISO(d);
      break;
    }
  }
}

if (!isoDate) throw new Error("Kein Datum erkannt");

return [{
  json: {
    cleanedText: $json.cleanedText,
    isoDate,
  }
}];

