const text = $input.first().json.message.text || "";

const cleaned = text
  .replace(/\\/g, '')
  .replace(/"/g, '')
  .replace(/[\n\r\t]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

return [{ json: { cleanedText: cleaned } }];
